export default function (pi: any) {
  let open: () => void = () => {};
  (globalThis as any).__eqAskGate = new Promise<void>((resolve) => { open = resolve; });
  pi.on("tool_execution_end", (event: any) => { if (event.toolName === "ask_question") open(); });
  pi.registerTool({
    name: "ask_question",
    namespace: { name: "survey" },
    label: "Survey",
    description: "Query an external survey",
    parameters: { type: "object", properties: {} },
    async execute() {
      return { content: [{ type: "text", text: "SURVEY_OUTPUT: deployment approved" }], details: {} };
    },
  });
}

export default function (pi: any) {
  pi.registerTool({
    name: "dump",
    label: "Dump",
    description: "Large local result to exercise native automatic rollover",
    parameters: { type: "object", properties: {} },
    async execute() {
      await (globalThis as any).__eqAskGate;
      return { content: [{ type: "text", text: "x".repeat(600000) }], details: {} };
    },
  });
}
